test_only_post_publication_harness:
from pathlib import Path
import subprocess,re,sys,json
scratch=Path(__file__).resolve().parent
repo=scratch.parents[2]
snapshot=repo/'build/t28-package/s1-uwp-release-01/clean-source'
tree=snapshot/'build/.ninja/x64'
source=(snapshot/'tests/run16s-exe/uwp.c').read_bytes()
needle=b'        BOOL appearance=!win2k || (actions && classic_pixels());'
patched=b'''        BOOL appearance=!win2k;
        if(win2k && actions){
            ULONGLONG deadline=GetTickCount64()+1500;
            do{
                appearance=classic_pixels();
                if(appearance)break;
                MsgWaitForMultipleObjects(0,NULL,FALSE,50,QS_ALLINPUT);
                MSG pending;
                while(PeekMessageW(&pending,NULL,0,0,PM_REMOVE)){
                    TranslateMessage(&pending);
                    DispatchMessageW(&pending);
                }
            }while(GetTickCount64()<deadline);
        }'''
assert source.count(needle)==1
observed=scratch/'uwp-settled-observer.c'
observed.write_bytes(source.replace(needle,patched))
command=subprocess.check_output(['ninja','-t','commands','launch-uwp-live'],cwd=tree,text=True).splitlines()[-1]
args=command.split('"cd . && ',1)[1].removesuffix(' && cd ."').split()
assert args[0].endswith('gcc.exe') and '&&' not in args
fixture=scratch/'uwp-settled-observer.obj'
subprocess.run([args[0],'-I',str(snapshot/'src'),'-DUNICODE','-D_UNICODE','-D_WIN32_WINNT=0x0A00',
                '-DNTW16S_STATIC','-std=c17','-O3','-Wall','-Wextra','-Werror','-c',str(observed),'-o',str(fixture)],check=True)
args=[str(fixture) if x=='CMakeFiles/launch-uwp-live.dir/tests/run16s-exe/uwp.c.obj' else
      str(scratch/'uwp-settled-observer.exe') if x=='launch-uwp-live.exe' else
      '-Wl,--out-implib,'+str(scratch/'libuwp-settled-observer.dll.a') if x=='-Wl,--out-implib,liblaunch-uwp-live.dll.a' else x for x in args]
assert str(fixture) in args
subprocess.run(args,cwd=tree,check=True)

source=(snapshot/'tests/ntw16s-dll/uwp/global.c').read_bytes()
needle=b'    wcscpy(tail+1,L"ntw16s64.dll");'
patch=b'''    wcscpy(tail+1,L"ntw16s64.dll");
    DWORD override_length=GetEnvironmentVariableW(L"UWP_TEST_PUBLISHED_DLL",dll,ARRAYSIZE(dll));
    if(!override_length || override_length>=ARRAYSIZE(dll))return 2;'''
assert source.count(needle)==1
observed=scratch/'uwp-published-global.c'
observed.write_bytes(source.replace(needle,patch))
command=subprocess.check_output(['ninja','-t','commands','core-uwp-global'],cwd=tree,text=True).splitlines()[-1]
args=command.split('"cd . && ',1)[1].removesuffix(' && cd ."').split()
assert args[0].endswith('gcc.exe') and '&&' not in args
fixture=scratch/'uwp-published-global.obj'
subprocess.run([args[0],'-I',str(snapshot/'src'),'-DUNICODE','-D_UNICODE','-D_WIN32_WINNT=0x0A00',
                '-DSTYLE_GLOBAL_MANAGER_TEST','-std=c17','-O3','-Wall','-Wextra','-Werror','-c',str(observed),'-o',str(fixture)],check=True)
args=[str(fixture) if x=='CMakeFiles/core-uwp-global.dir/tests/ntw16s-dll/uwp/global.c.obj' else
      str(scratch/'uwp-published-global.exe') if x=='core-uwp-global.exe' else
      '-Wl,--out-implib,'+str(scratch/'libuwp-published-global.dll.a') if x=='-Wl,--out-implib,libcore-uwp-global.dll.a' else x for x in args]
assert str(fixture) in args
subprocess.run(args,cwd=tree,check=True)
